# Source for q/spi-safety-qa.js: Safety (bioeffects, D1), Patient care (D1), Quality assurance (D5).
S="Safety"; PC="Patient care"; QA="Quality assurance"
Q=[
# --- Bioeffects ---
(S,"The two main mechanisms by which ultrasound can affect tissue are:","Thermal and mechanical (cavitation)",["Ionizing and chemical","Electrical and magnetic","Thermal and ionizing"],"Ultrasound is non-ionizing. Possible bioeffects come from heating and from mechanical effects such as cavitation and radiation force.","F"),
(S,"Cavitation is:","The interaction of sound with gas bubbles, which can oscillate or collapse",["Heating of bone by absorption","Bending of sound at a boundary","Ionization of tissue"],"Stable cavitation: bubbles oscillate without bursting. Inertial (transient) cavitation: bubbles collapse violently, which can damage nearby cells.","F"),
(S,"Which type of cavitation is more harmful?","Inertial (transient) cavitation",["Stable cavitation","Both are equally harmless","Neither occurs in tissue"],"Bubble collapse can create very high local pressures and temperatures. Stable cavitation causes microstreaming but is less damaging.","F"),
(S,"The mechanical index (MI) estimates the likelihood of:","Cavitation and other mechanical bioeffects",["Tissue heating","Aliasing","Electrical shock"],"MI is calculated from the peak rarefactional pressure and the frequency.","F"),
(S,"The mechanical index increases when:","Peak rarefactional pressure rises or frequency falls",["Frequency rises","Output power falls","Gain is increased"],"MI = peak rarefactional pressure (MPa) ÷ √frequency (MHz). Low frequencies and high pressures favor cavitation.","F"),
(S,"The FDA upper limit for the mechanical index in most diagnostic applications (excluding the eye) is:","1.9",["0.23","5.0","0.5"],"The ophthalmic limit is much lower, 0.23.","C"),
(S,"The thermal index (TI) estimates:","The potential rise in tissue temperature",["The chance of cavitation","Image brightness","Doppler shift"],"TI is the ratio of acoustic power to the power needed to raise tissue temperature by 1 °C. A TI of 1 suggests a possible rise of about 1 °C.","F"),
(S,"TIB (thermal index for bone) applies when:","The beam's focus falls on or near bone, such as fetal bone in the second and third trimesters",["Imaging soft tissue only","Bone is at the skin surface","There is no bone in the beam"],"TIS is for soft tissue, TIB for bone at the focus, and TIC for cranial bone near the surface (transcranial).","F"),
(S,"TIC (thermal index for cranial bone) is used when:","Bone lies at or near the skin surface, such as in transcranial imaging",["Bone is at the focus deep in the body","Only soft tissue is imaged","Imaging a fluid-filled cyst"],"Bone near the transducer absorbs strongly close to the surface.","F"),
(S,"Which tissue heats most when exposed to ultrasound?","Bone",["Fat","Blood","Amniotic fluid"],"Bone absorbs sound strongly, so it heats faster than soft tissue or fluid.","F"),
(S,"Which mode usually has the highest SPTA intensity and potential for heating?","Pulsed-wave Doppler",["B-mode imaging","M-mode","Color Doppler with a wide box"],"PW Doppler concentrates many pulses along one line at one depth with a high duty factor.","F"),
(S,"Tissues containing gas, such as lung and bowel, are most sensitive to:","Mechanical (cavitation) bioeffects",["Thermal effects only","Ionizing effects","No bioeffects"],"Gas bodies act as cavitation nuclei. Lung hemorrhage has been seen in animal studies at diagnostic exposures.","C"),
(S,"Ultrasound contrast agents raise bioeffect concerns mainly because:","Microbubbles act as cavitation nuclei",["They ionize tissue","They raise blood viscosity","They absorb heat strongly"],"Using the lowest MI needed for contrast imaging also reduces bubble destruction.","F"),
(S,"Contrast echocardiography is usually performed at a low mechanical index because:","High MI destroys the microbubbles",["Low MI increases heating","High MI lowers frame rate","Low MI raises frequency"],"Low-MI imaging lets bubbles oscillate and return harmonic signals without bursting. High-MI 'flash' frames are used briefly to destroy bubbles for perfusion studies.","F"),
(S,"The AIUM's position on diagnostic ultrasound is that:","No independently confirmed adverse effects have been reported in patients at diagnostic intensities, but prudent use is advised",["Diagnostic ultrasound causes cancer","Ultrasound is ionizing radiation","There are no limits on output"],"The benefit to patients exceeds the risk, when used prudently (ALARA) by qualified people.","F"),
(S,"ALARA stands for:","As low as reasonably achievable",["Always lower all ranges available","Adjust levels as required always","Acoustic limits are recommended always"],"Use the lowest output and shortest scan time that still answers the clinical question.","F"),
(S,"Which practice follows ALARA?","Using receiver gain to brighten the image before raising output power",["Leaving the probe on the patient while talking","Using PW Doppler for the whole exam","Setting output to maximum to save time"],"Also freeze the image when not scanning, limit Doppler time and watch the MI and TI displays.","F"),
(S,"Which factor does NOT change patient exposure?","Receiver gain",["Output power","Scan time","Choice of mode (B-mode vs PW Doppler)"],"Gain only amplifies returning echoes. Exposure depends on what is transmitted and for how long.","F"),
(S,"In vitro bioeffects studies are performed:","On cells or tissue outside the living body",["In living animals or people","As population surveys","With mathematical models only"],"In vivo = in a living body. Epidemiologic studies look at populations.","F"),
(S,"An epidemiologic study of ultrasound safety:","Compares outcomes in large groups of exposed and unexposed people",["Tests cells in a dish","Measures output with a hydrophone","Uses a tissue-equivalent phantom"],"Such studies can show associations but not always cause and effect.","F"),
(S,"A hydrophone is used to measure:","Acoustic pressure in the beam, used to calculate intensity",["Transducer temperature","Image resolution","Frame rate"],"A tiny piezoelectric probe placed in a water tank maps pressure throughout the beam.","F"),
(S,"A radiation force balance measures:","Total acoustic power of the beam",["Peak pressure at one point","Temperature rise","Lateral resolution"],"The beam pushes on a target; the force is proportional to power.","C"),
(S,"A thermocouple measures:","Temperature",["Pressure","Power","Beam width"],"Thermocouples can measure heating at the transducer face or in test materials.","F"),
(S,"The FDA maximum ISPTA (derated) for most diagnostic applications is:","720 mW/cm²",["100 mW/cm²","10 W/cm²","1,000 W/cm²"],"Track 3 regulation limits ISPTA.3 to 720 mW/cm² and MI to 1.9, with the output display letting the user manage exposure.","C"),
(S,"Derated intensity values account for:","Attenuation in tissue, so they estimate exposure inside the body rather than in water",["Electrical leakage","The transducer cable length","Gain settings"],"Measurements in water are reduced (derated) by about 0.3 dB/cm/MHz to estimate tissue values.","C"),
(S,"Which patient group calls for the most caution with thermal effects?","Pregnant patients, especially when the beam is on fetal bone, or a febrile patient",["Adults with normal temperature having a short abdominal scan","Patients with healed skin wounds","Patients wearing a pacemaker"],"Heat added to a fever, or concentrated at developing bone, raises concern. Keep TI low and dwell time short.","F"),
(S,"Increasing which setting raises both MI and TI?","Output (transmit) power",["Receiver gain","Dynamic range","Persistence"],"Raising transmitted power increases pressure and intensity in the patient.","F"),
(S,"Lowering the transducer frequency, with all else the same, will:","Raise the MI",["Lower the MI","Not change the MI","Eliminate cavitation"],"MI is divided by the square root of frequency, so lower frequencies give higher MI.","C"),
(S,"Radiation force and acoustic streaming are:","Non-cavitational mechanical effects of ultrasound",["Thermal effects","Ionizing effects","Electrical hazards"],"Sound pushes on tissue and fluid. Streaming is the movement of fluid caused by the beam.","C"),
(S,"Transducer self-heating is a concern mainly because:","Heat at the transducer face can warm the skin, especially during long TEE studies",["It changes the PRF","It increases gain","It causes aliasing"],"TEE probes include a temperature sensor and shut off if the tip becomes too hot.","F"),
# --- Patient care ---
(PC,"Before starting an echo, patient identity should be confirmed with:","At least two identifiers, such as full name and date of birth",["The room number only","The patient's diagnosis","The ordering physician's name"],"Two identifiers prevent scanning or reporting on the wrong patient.","F"),
(PC,"Work-related musculoskeletal disorders in sonographers are reduced by:","Keeping the scanning arm close to the body, the wrist neutral and adjusting the bed and chair height",["Holding the arm fully abducted for long periods","Gripping the probe tightly","Twisting the neck toward the monitor"],"Arm abduction under about 30°, neutral wrist, support for the cable and regular breaks all help.","F"),
(PC,"A sonographer finds a large pericardial effusion with signs of tamponade. The correct action is to:","Notify the interpreting physician immediately as a critical finding",["Finish the routine protocol and file the images","Tell the patient the diagnosis","Wait for the formal report"],"Critical findings need prompt communication by the lab's protocol.","F"),
(PC,"Who should explain the diagnosis and results to the patient?","The interpreting or ordering physician",["The sonographer during the scan","The receptionist","Any staff member"],"Sonographers gather images and report findings to the physician, who interprets and communicates diagnoses.","F"),
(PC,"Informed consent is usually required before:","A transesophageal echocardiogram",["A standard transthoracic echo","Applying ECG leads","Taking a patient's height"],"TEE is invasive and involves sedation, so the physician obtains informed consent.","F"),
(PC,"Patient health information must be protected according to:","HIPAA",["ALARA","DICOM","AIUM"],"Do not discuss patients where others can hear, and keep records and images secure.","F"),
(PC,"If a patient becomes unresponsive during an echo, the sonographer should first:","Check responsiveness and breathing and call for help (activate the emergency response)",["Continue scanning to document the event","Leave to find the physician without calling for help","Give medication"],"Follow basic life support steps and the facility's emergency procedure.","F"),
(PC,"A patient with orthopnea cannot lie flat. The sonographer should:","Raise the head of the bed and adapt the views",["Insist on a flat position","Cancel the exam","Scan only in the prone position"],"Patient comfort and safety come first. Many views can be obtained semi-upright.","F"),
(PC,"Before a stress echo, the sonographer should check:","That the order, history, medications and contraindications have been reviewed",["Only the patient's height","The patient's insurance only","Nothing beyond the order"],"Clinical history guides the exam and helps catch contraindications.","F"),
(PC,"Correct ECG lead placement during echo matters because:","Accurate timing of systole and diastole depends on it",["It increases frame rate","It improves penetration","It is required for color Doppler to work"],"End-diastolic and end-systolic measurements and Doppler timing rely on a clear ECG trace.","F"),
# --- Infection control ---
(QA,"The single most effective way to prevent the spread of infection is:","Hand hygiene",["Wearing a gown","Using sterile gel for every patient","Cleaning the monitor"],"Clean hands before and after every patient contact, and after removing gloves.","F"),
(QA,"When caring for a patient with C. difficile infection, hand hygiene should use:","Soap and water",["Alcohol-based rub only","No hand cleaning if gloves were worn","Dry wipes"],"Alcohol does not kill C. difficile spores; mechanical washing removes them.","C"),
(QA,"Standard precautions mean:","Treating all blood and body fluids from every patient as potentially infectious",["Only isolating patients with known infections","Wearing a mask at all times","Using sterile technique for every exam"],"Standard precautions apply to every patient, every time.","F"),
(QA,"Under the Spaulding classification, a transthoracic probe that touches intact skin is:","Noncritical, needing low- or intermediate-level disinfection",["Critical, needing sterilization","Semicritical, needing high-level disinfection","Exempt from cleaning"],"Wipe it with an approved disinfectant after cleaning off gel.","F"),
(QA,"A TEE probe that contacts mucous membranes is classified as:","Semicritical, needing high-level disinfection",["Noncritical","Critical, needing low-level disinfection","Exempt"],"After every use: clean, inspect, leak-test and high-level disinfect according to the manufacturer.","F"),
(QA,"A probe used in a sterile surgical field or on non-intact skin should be:","Covered with a sterile sheath and used with sterile gel",["Used bare with regular gel","Wiped with water only","Avoided entirely"],"Sterile covers and sterile gel protect against infection at open or invasive sites.","F"),
(QA,"Before each use, a TEE probe should be inspected for:","Bite marks, cracks and damage that could expose the patient to electrical current",["Image brightness","Frame rate","Gel residue on the handle only"],"Damage can cause electrical leakage or harbor organisms. Perform the electrical leakage test as required.","F"),
(QA,"Which isolation precaution is needed for tuberculosis?","Airborne precautions with an N95 respirator",["Contact precautions only","Droplet precautions with a surgical mask","Standard precautions only"],"TB spreads by tiny airborne particles. Patients are placed in negative-pressure rooms.","F"),
(QA,"Influenza calls for which isolation precaution?","Droplet precautions",["Airborne precautions","Contact precautions only","No precautions"],"Wear a surgical mask within about 3 to 6 feet of the patient.","F"),
(QA,"MRSA calls for which isolation precaution?","Contact precautions (gown and gloves)",["Airborne precautions","Droplet precautions only","No precautions"],"Clean the equipment, including the probe and cables, thoroughly after the exam.","F"),
(QA,"Multi-use gel bottles should:","Not be refilled or used for invasive procedures, and should be kept clean",["Be refilled from a larger container","Be warmed in the patient's bed","Be shared freely between isolation rooms"],"Contaminated gel has caused outbreaks. Use single-use sterile gel for procedures and non-intact skin.","C"),
(QA,"The correct order for removing PPE usually starts with:","Gloves",["Mask","Goggles","Hand hygiene only"],"Gloves are most contaminated. A common sequence: gloves, goggles or face shield, gown, mask, then hand hygiene.","C"),
(QA,"Used needles should be:","Placed in a sharps container without recapping",["Recapped with two hands","Placed in regular trash","Bent before disposal"],"Recapping causes needlestick injuries. Use safety devices and sharps bins.","F"),
# --- Equipment safety and QA ---
(QA,"A transducer with a cracked housing or frayed cable should be:","Removed from service and reported",["Used carefully until the end of the day","Taped and used","Used only for short exams"],"Damage risks electrical shock and infection, and degrades images.","F"),
(QA,"A tissue-equivalent phantom is designed to have:","Speed of sound and attenuation similar to soft tissue",["The speed of sound in air","No attenuation","The impedance of bone"],"Because it behaves like tissue, it can test penetration, sensitivity, grayscale and resolution realistically.","F"),
(QA,"The AIUM 100 mm test object differs from a tissue-equivalent phantom because it:","Has no tissue-like attenuation or texture, so it cannot assess grayscale performance",["Has tissue-like texture","Measures Doppler velocity","Contains moving blood"],"It contains rods in a medium with a speed of 1540 m/s, useful for distance accuracy, dead zone and resolution.","C"),
(QA,"The dead zone is:","The region closest to the transducer where imaging is not reliable",["The far field beyond the focus","The area behind a shadow","The region outside the color box"],"Ringing of the crystal and the matching layer prevent imaging very close to the face. It is measured with a phantom.","F"),
(QA,"The dead zone is reduced by:","Higher frequency and more damping",["Lower frequency","Less damping","Higher gain"],"Shorter pulses end sooner, so echoes can be received closer to the transducer.","C"),
(QA,"Registration accuracy tests whether:","Reflectors are displayed in their correct positions",["Doppler velocities are accurate","The ECG is synchronized","The transducer is clean"],"The phantom's known rod positions are compared with where the machine places them.","F"),
(QA,"Vertical (range) distance accuracy checks:","Depth measurements along the beam, which depend on the assumed speed of sound",["Measurements side to side","Grayscale levels","Doppler angle"],"Errors suggest a fault in timing or speed settings.","F"),
(QA,"Horizontal distance accuracy checks:","Measurements perpendicular to the beam",["Depth measurements","Penetration","Velocity accuracy"],"It tests the scan converter and the beam's lateral positioning.","F"),
(QA,"Sensitivity (penetration) testing measures:","The deepest depth at which the system can detect weak reflectors",["The closest imaging depth","Lateral resolution","Doppler aliasing"],"Falling sensitivity over time can mean the transducer is degrading.","F"),
(QA,"Axial resolution is tested in a phantom using:","Rod groups spaced at decreasing distances along the beam",["Rods spaced side by side","Cysts of different brightness","A moving string"],"The smallest separation at which two rods still appear separate is the axial resolution.","F"),
(QA,"Contrast resolution is tested in a phantom using:","Targets of slightly different echogenicity",["Rods spaced along the beam","A moving string","A hydrophone"],"Cylinders of varying brightness check the system's ability to show subtle differences.","F"),
(QA,"A Doppler string phantom tests:","Velocity accuracy, using a string moving at a known speed",["Grayscale resolution","Dead zone","Transducer temperature"],"Flow phantoms with pumped blood-mimicking fluid can also check depth accuracy and sensitivity of Doppler.","F"),
(QA,"A slice-thickness phantom assesses:","Elevational resolution",["Axial resolution","Temporal resolution","Velocity accuracy"],"It contains a thin, angled sheet that shows how thick the beam is in the elevational plane.","C"),
(QA,"Quality assurance testing should be:","Performed routinely and documented, with results compared over time",["Done only when the machine breaks","Never documented","Performed only by the patient"],"Trends in phantom results catch slow deterioration before it affects diagnoses.","F"),
(QA,"Electrical leakage testing of a TEE probe is performed to:","Make sure no current can leak to the patient through damaged insulation",["Check image brightness","Measure the PRF","Test Doppler accuracy"],"The probe sits against the esophagus close to the heart, so electrical safety is critical.","F"),
(QA,"Uniformity testing in a phantom checks that:","Similar reflectors look the same brightness across the image",["Velocity is accurate","The dead zone is small","Frame rate is constant"],"Non-uniform areas can mean a failing element or channel.","C"),
# --- Statistics ---
(QA,"Sensitivity of a test is:","The ability to correctly detect disease when it is present: TP ÷ (TP + FN)",["The ability to correctly identify normal patients","TP ÷ (TP + FP)","TN ÷ (TN + FN)"],"A highly sensitive test rarely misses disease.","F"),
(QA,"Specificity of a test is:","The ability to correctly identify the absence of disease: TN ÷ (TN + FP)",["TP ÷ (TP + FN)","TP ÷ (TP + FP)","(TP + TN) ÷ total"],"A highly specific test rarely calls normal patients abnormal.","F"),
(QA,"Positive predictive value (PPV) is:","TP ÷ (TP + FP)",["TP ÷ (TP + FN)","TN ÷ (TN + FN)","TN ÷ (TN + FP)"],"PPV is the chance that a positive result is truly positive.","F"),
(QA,"Negative predictive value (NPV) is:","TN ÷ (TN + FN)",["TN ÷ (TN + FP)","TP ÷ (TP + FP)","TP ÷ (TP + FN)"],"NPV is the chance that a negative result is truly negative.","F"),
(QA,"Accuracy of a test is:","(TP + TN) ÷ all tests",["TP ÷ all tests","TP ÷ (TP + FP)","TN ÷ (TN + FP)"],"Accuracy is the proportion of all results that were correct.","F"),
(QA,"A false positive result means:","The test says disease is present, but the gold standard shows it is absent",["The test misses real disease","The test and gold standard agree on disease","The test and gold standard agree on normal"],"A false negative is the opposite: disease present but the test says normal.","F"),
(QA,"Echo finds aortic stenosis in 45 patients confirmed by catheterization (TP), misses 5 (FN), wrongly calls 10 abnormal (FP) and correctly calls 40 normal (TN). What is the sensitivity?","90%",["80%","82%","89%"],"Sensitivity = TP ÷ (TP + FN) = 45 ÷ 50 = 90%.","C"),
(QA,"Using TP 45, FN 5, FP 10, TN 40, what is the specificity?","80%",["90%","82%","89%"],"Specificity = TN ÷ (TN + FP) = 40 ÷ 50 = 80%.","C"),
(QA,"Using TP 45, FN 5, FP 10, TN 40, what is the positive predictive value?","82%",["90%","80%","89%"],"PPV = TP ÷ (TP + FP) = 45 ÷ 55 ≈ 82%.","C"),
(QA,"Using TP 45, FN 5, FP 10, TN 40, what is the negative predictive value?","89%",["80%","90%","82%"],"NPV = TN ÷ (TN + FN) = 40 ÷ 45 ≈ 89%.","C"),
(QA,"Using TP 45, FN 5, FP 10, TN 40, what is the overall accuracy?","85%",["90%","80%","45%"],"Accuracy = (45 + 40) ÷ 100 = 85%.","C"),
(QA,"The 'gold standard' in a diagnostic study is:","The best available reference test that the new test is compared against",["The cheapest test","The newest test","Any ultrasound result"],"For valve disease this might be surgery or catheterization findings.","F"),
(QA,"A test that rarely misses disease but often gives false alarms has:","High sensitivity and low specificity",["High specificity and low sensitivity","High specificity and high PPV","Low sensitivity and low specificity always"],"Screening tests are often designed this way, then followed by more specific tests.","F"),
(QA,"Reproducibility of measurements between two sonographers is called:","Interobserver variability (or agreement)",["Intraobserver variability","Sensitivity","Accuracy"],"Intraobserver variability is how consistent one person is when repeating the same measurement.","F"),
(QA,"Precision (reliability) describes:","How closely repeated measurements agree with each other",["How close a measurement is to the true value","The number of patients tested","The speed of the scan"],"A test can be precise but inaccurate if it consistently measures the wrong value.","C"),
(QA,"Increasing a test's cutoff so fewer patients are called abnormal will usually:","Raise specificity and lower sensitivity",["Raise both sensitivity and specificity","Lower both","Have no effect"],"There is a trade-off: stricter criteria miss more disease but give fewer false positives.","C"),
(QA,"If disease becomes more common in the tested population, the positive predictive value usually:","Increases",["Decreases","Stays the same","Becomes zero"],"PPV and NPV depend on prevalence; sensitivity and specificity do not.","C"),
(QA,"Which values do NOT depend on how common the disease is in the population tested?","Sensitivity and specificity",["PPV and NPV","Accuracy and PPV","NPV only"],"Sensitivity and specificity describe the test itself; predictive values depend on prevalence.","C"),
]
